import json,sys
T={'chapitre','lecon','section','notion','definition','caracteristique','categorie','signe','cause','consequence','condition','probleme','solution','question','theorie','argument','critique','nuance','comparaison','avantage','inconvenient','methode','etape','conseil','exercice','objectif','date','chiffre','formule','etude','citation','personne','texte','juris','doctrine','fond','forme','effet','exception','exemple','piege','retenir','idee'}
d=json.load(open(sys.argv[1]));E=[];HORS='--hors-droit' in sys.argv
assert d.get('format')=='ratio' and d.get('version')==2 and d.get('kind')=='course'
cid={c['id'] for c in d['courses']};mids=set()
for m in d['maps']:
  p=m['id'];E+=[p+': id de carte en double'] if p in mids else [];mids.add(p)
  if m.get('courseId') not in cid:E.append(p+': courseId inconnu')
  if m.get('needsLayout') is not True:E.append(p+': needsLayout manquant')
  ids=[n['id'] for n in m['nodes']];S=set(ids)
  if len(S)!=len(ids):E.append(p+': id de nœud en double')
  titles=[n['title'].strip().lower() for n in m['nodes']]
  if len(set(titles))!=len(titles):E.append(p+': titres en double')
  for n in m['nodes']:
    if n.get('type') not in T:E.append(p+'/'+n['id']+': type inconnu')
    if n.get('logic') not in (None,'et','ou'):E.append(p+'/'+n['id']+': logic invalide')
  par={};eids=set()
  for e in m['edges']:
    if e['id'] in eids:E.append(p+': id d\'arête en double')
    eids.add(e['id'])
    if e['from'] not in S or e['to'] not in S or e['from']==e['to']:E.append(p+'/'+e['id']+': extrémité invalide')
    if e['kind']=='tree':
      if e['to'] in par:E.append(p+'/'+e['to']+': deux parents')
      par[e['to']]=e['from']
    elif not e.get('label'):E.append(p+'/'+e['id']+': lien sans libellé')
  roots=[i for i in ids if i not in par]
  if len(roots)!=1:E.append(p+': %d racines'%len(roots))
  for i in ids:
    seen=set();j=i
    while j in par:
      if j in seen:E.append(p+': cycle');break
      seen.add(j);j=par[j]
W=[]
for m in d['maps']:
  p=m['id'];par={e['to']:e['from'] for e in m['edges'] if e['kind']=='tree'};ids=[n['id'] for n in m['nodes']];T={n['id']:n for n in m['nodes']}
  root=[i for i in ids if i not in par][0] if ids else None
  kids=[e['to'] for e in m['edges'] if e['kind']=='tree' and e['from']==root]
  if not 3<=len(kids)<=7:W.append(p+': %d branches sous la racine (3–7)'%len(kids))
  for k in kids:
    if T[k]['type'] in ('exemple','juris'):W.append(p+': '+T[k]['title'][:30]+' ('+T[k]['type']+') directement sous la racine')
  top=lambda i:(i if par.get(i)==root else top(par[i])) if i in par else i
  L=[e for e in m['edges'] if e['kind']=='link'];lim=6 if len(ids)>30 else 4
  if len(L)>lim:W.append(p+': %d renvois (max %d)'%(len(L),lim))
  for e in L:
    a,b=top(e['from']),top(e['to'])
    if a in kids and b in kids and abs(kids.index(a)-kids.index(b))>1:W.append(p+': renvoi lointain '+T[e['from']]['title'][:25]+' → '+T[e['to']]['title'][:25]+' (→ [[Titre]] dans la note ?)')
    if par.get(e['to'])==e['from'] or par.get(e['from'])==e['to']:W.append(p+': renvoi parent ↔ enfant')
    if len(e.get('label',''))>20:W.append(p+': libellé long « '+e['label']+' »')
  if not 12<=len(ids)<=45:W.append(p+': %d nœuds (12–45, cible 15–35)'%len(ids))
import re
for m in d['maps']:
  p=m['id'];T={n['id']:n for n in m['nodes']};titles={n['title'].strip().lower().replace('’',"'") for n in m['nodes']}
  ns=[n for n in m['nodes'] if n['type'] not in ('chapitre','lecon','section')]
  hl=sum(1 for n in ns if '==' in n.get('note',''))
  if ns and hl/len(ns)<0.2:W.append(p+': surligné dans %d %% des notes (≥ 20 %% par carte, 30–70 %% sur le cours)'%(100*hl//len(ns)))
  for n in m['nodes']:
    for t in re.findall(r'\[\[([^\]]+)\]\]',n.get('note','')):
      if t.strip().lower().replace('’',"'") not in titles:W.append(p+': [['+t+']] ne correspond à aucun titre de la carte')
  for n in m['nodes']:
    if n['type']=='methode':
      ks=[e['to'] for e in m['edges'] if e['kind']=='tree' and e['from']==n['id']]
      if 3<=len(ks)<=6 and any(len(T[k]['title'])>34 for k in ks):W.append(p+': étape de méthode > 34 caractères (pas de frise) sous '+n['title'][:30])
for m in d['maps']:
  p=m['id'];ns=m['nodes'];N=len(ns)
  if HORS:
    for n in ns:
      if n['type'] in ('fond','forme','effet','juris','doctrine'):W.append(p+': type juridique « '+n['type']+' » hors droit : '+n['title'][:40]+' (voir faux_amis)')
  for n in ns:
    if n['type']=='exception' and not re.search(r"sauf|except|hormis|à moins|ne s.applique pas|sauf si|en dehors de",(n['title']+' '+n.get('note','')).lower()):W.append(p+': exception sans règle écartée (test « SAUF ») : '+n['title'][:40]+' → nuance, critique, piege ?')
  idees=sum(1 for n in ns if n['type']=='idee')
  if N>=12 and idees>0.25*N:W.append(p+': %d %% de nœuds « idee » (≤ 25 %%) — choisir des types précis'%(100*idees//N))
for m in d['maps']:
  p=m['id'];T={n['id']:n for n in m['nodes']};par={e['to']:e['from'] for e in m['edges'] if e['kind']=='tree'}
  def txt(n): return (n['title']+' '+n.get('note','')).lower()
  for n in m['nodes']:
    t=n['type'];P=T.get(par.get(n['id']));pt=P['type'] if P else None;x=txt(n);ti=n['title'][:38]
    if t=='etape' and pt!='methode':W.append(p+': étape hors méthode : '+ti+' → conseil ?')
    if t=='solution' and pt not in ('probleme','question','solution','section','lecon','chapitre'):W.append(p+': solution sans problème nommé au-dessus : '+ti+' → conseil ?')
    if t in ('avantage','inconvenient') and pt not in ('solution','comparaison','categorie','theorie','methode','notion'):W.append(p+': '+t+' sans option au-dessus : '+ti+' → consequence ?')
    if t=='consequence' and re.search(r"\bpour que\b|\bafin de\b|\bafin que\b|\bbut\b",x):W.append(p+': conséquence formulée comme un but : '+ti+' → objectif ?')
    if t=='cause' and re.search(r"\bil faut\b|\bà condition\b|\bseulement si\b|\bnécessaire\b",x) and not re.search(r"parce que|à cause|provoque|entraîne",x):W.append(p+': cause formulée comme une condition : '+ti+' → condition ?')
    if t in ('nuance','critique','piege','probleme') and re.search(r"\bsauf (si|dans|lorsque|quand)\b|à moins que|\bexcepté\b",x) and pt in ('fond','forme','texte'):W.append(p+': '+t+' qui écarte une règle juridique : '+ti+' → exception ?')
    if t=='piege' and not re.search(r"erreur|croi|confond|faux|idée reçue|éviter|ne pas|≠|attention|piège|pense",x):W.append(p+': piège sans erreur nommée : '+ti+' → nuance ?')
print('\n'.join('⚠ '+w for w in W))
print('\n'.join(E) or 'OK — %d cartes, %d nœuds'%(len(d['maps']),sum(len(m['nodes']) for m in d['maps'])))
